function bindProfilePhotoControls(r){
  const input=$('#profilePhotoInput');if(input)input.onchange=async e=>{const f=e.target.files?.[0];if(!f)return;input.disabled=true;try{const photo=await optimizeProfilePhoto(f);mutateAndSave(()=>{r.basics.photo=photo;r.settings.showPhoto=true},{onSuccess:()=>{renderEditor();renderPreview();renderTemplates()},success:'Foto de perfil guardada localmente'})}catch(err){toast(err.message)}finally{if(input)input.disabled=false}};
  const remove=$('#profilePhotoRemove');if(remove)remove.onclick=()=>mutateAndSave(()=>{r.basics.photo='';r.settings.showPhoto=false},{onSuccess:()=>{renderEditor();renderPreview()},success:'Foto eliminada'});
  const show=$('#profilePhotoShow');if(show)show.onchange=e=>mutateAndSave(()=>{r.settings.showPhoto=!!e.target.checked},{onSuccess:renderPreview});
  $$('[data-photo-adjust]').forEach(el=>el.oninput=e=>{const key=e.target.dataset.photoAdjust,val=Number(e.target.value);r.settings[key]=key==='photoZoom'?Math.max(1,Math.min(2.5,val)):Math.max(-50,Math.min(50,val));scheduleSave();renderPreview()});
}
function fileToBase64(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>{const raw=String(fr.result||'');resolve(raw.includes(',')?raw.split(',').pop():raw)};fr.onerror=()=>reject(new Error('No se pudo leer el archivo.'));fr.readAsDataURL(file)})}

