  if(action==='open'){state.currentId=id;const persisted=save();setView('editor');renderPreview();updateQuickScore();if(!persisted)toast('CV abierto · no se pudo recordar la selección por falta de espacio.');return}
  if(action==='clone'){mutateAndSave(()=>{const r=cloneResume(d.resume);r.title=`${d.resume.title} · variante`;state.documents.push({id:r.id,name:r.title,resume:r,updatedAt:Date.now()});state.currentId=r.id},{onSuccess:renderHome,success:'Variante creada'});return}
